// Logs/reports can contain identifying application evidence: keep them ignored.
import { spawnSync, execFileSync } from "node:child_process";
import { existsSync, mkdirSync, openSync, closeSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { assertProductionBuild, assertRequiredResults } from "./acceptance-results.mjs";

if (existsSync(".env")) process.loadEnvFile(".env");
const tier = process.argv[2];
if (!["fast", "required"].includes(tier)) throw new Error("Use acceptance.mjs fast|required");
const directory = resolve(`.qa/acceptance-${tier}-${Date.now()}`);
mkdirSync(directory, { recursive: true });
const revision = execFileSync("git", ["rev-parse", "HEAD"], { encoding: "utf8" }).trim();
const worktreeDirty = Boolean(execFileSync("git", ["status", "--porcelain"], { encoding: "utf8" }).trim());
const migrationHead = readdirSync("supabase/migrations").filter(file => file.endsWith(".sql")).sort().at(-1);
const result = { revision, worktreeDirty, migrationHead, tier, environment: "self-hosted backend", startedAt: new Date().toISOString(), provider: "optional; not run; core-journey.gated.spec.ts excluded because it invokes the live provider; deterministic mocks are not provider evaluation", checks: [] };

function run(name, script, args = [], env = {}) {
  const log = openSync(`${directory}/${name}.log`, "w");
  let child;
  try { child = spawnSync(process.execPath, [script, ...args], { env: { ...process.env, ...env }, stdio: ["ignore", log, log] }); }
  finally { closeSync(log); }
  result.checks.push({ name, passed: child.status === 0 });
  if (child.error || child.status !== 0) throw new Error(`${name} failed; review ignored acceptance logs`);
  console.log(`PASS: ${name}`);
}

try {
  if (tier === "fast") {
    const npm = process.env.npm_execpath;
    if (!npm) throw new Error("Run through npm run acceptance:fast");
    for (const name of ["test", "lint", "build"]) run(name, npm, ["run", name]);
    result.buildId = readFileSync(".next/BUILD_ID", "utf8").trim();
  } else {
    const latestFast = readdirSync(".qa").filter(name => /^acceptance-fast-\d+$/.test(name)).sort().at(-1);
    let fast;
    try { if (latestFast) fast = JSON.parse(readFileSync(`.qa/${latestFast}/result.json`, "utf8")); } catch { /* Missing/incomplete evidence is rejected below. */ }
    const buildId = existsSync(".next/BUILD_ID") ? readFileSync(".next/BUILD_ID", "utf8").trim() : undefined;
    assertProductionBuild(fast, { revision, worktreeDirty, buildId });
    result.buildId = buildId;
    const missing = ["SUPABASE_DB_URL", "SUPABASE_SERVICE_ROLE_KEY", "NEXT_PUBLIC_SUPABASE_URL", "NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY"].filter(name => !process.env[name]);
    const state = process.env.E2E_STORAGE_STATE || "e2e/.auth.json";
    if (!existsSync(state)) missing.push("E2E_STORAGE_STATE (or e2e/.auth.json)");
    if (missing.length) throw new Error(`Required prerequisites missing: ${missing.join(", ")}`);
    run("privacy", "scripts/check-private-data.mjs");
    run("migrations", "supabase/tests/migrations.mjs");
    const units = `${directory}/units.json`, browser = `${directory}/browser.json`;
    // Live fixture DDL locks shared auth/workspace tables. Serialize files while
    // retaining each test's deliberate concurrent database connections.
    run("units", "node_modules/vitest/vitest.mjs", ["run", "--no-file-parallelism", "--reporter=json", `--outputFile=${units}`], { RUN_RESERVATION_DB_TESTS: "1", RUN_IMPORT_EXCLUSION_DB_TESTS: "1", RUN_IMPORT_ROW_UNDO_DB_TESTS: "1", RUN_VERIFIED_EVIDENCE_DB_TESTS: "1", RUN_INVESTIGATION_REQUEST_DB_TESTS: "1" });
    const unitReport = JSON.parse(readFileSync(units, "utf8"));
    result.units = { total: unitReport.numTotalTests, failed: unitReport.numFailedTests, skipped: unitReport.numPendingTests };
    assertRequiredResults("vitest", unitReport);
    const specs = readdirSync("e2e").filter(file => file.endsWith(".spec.ts") && file !== "core-journey.gated.spec.ts").map(file => `e2e/${file}`);
    // Run the verified production build without HMR or a live provider key.
    run("browser", "node_modules/@playwright/test/cli.js", ["test", ...specs, "--workers=1", "--reporter=json", `--output=${directory}/browser-artifacts`], { PLAYWRIGHT_JSON_OUTPUT_FILE: browser, OPENAI_API_KEY: "", E2E_PRODUCTION_BUILD: "1", CI: "1" });
    const browserReport = JSON.parse(readFileSync(browser, "utf8"));
    result.browser = browserReport.stats;
    assertRequiredResults("playwright", browserReport);
  }
  result.passed = true;
} catch (error) {
  result.passed = false;
  result.failure = error.message;
  console.error(error.message);
  process.exitCode = 1;
} finally {
  result.finishedAt = new Date().toISOString();
  writeFileSync(`${directory}/result.json`, JSON.stringify(result, null, 2));
  console.log(`Acceptance summary: ${directory}/result.json`);
}
# Database checks

These scripts test the SQL functions, row-level security and concurrency of the self-hosted database. They read `SUPABASE_DB_URL` and the Supabase keys from `.env` (written by `npm run setup`).

## Migrations and regressions

```sh
node supabase/tests/migrations.mjs
```

Replays every migration into a temporary schema, compares it with the current schema (columns, constraints, indexes, RLS, policies, views, triggers, functions), and runs the `.sql` regression fixtures on both. Everything runs in rollback-only transactions; migration history stays unchanged and the temporary schema is removed.

`workspace-isolation.sql` seeds two synthetic users with records in every application table and checks, as the `authenticated` role, that neither can see or change the other's data. Keep its fixtures and RPC cases in step when adding tables or mutations.

Single regressions run with their `run-*.mjs` script, for example `node supabase/tests/run-goal-reservations.mjs`. `run-sql.mjs` runs the import-review fixture.

## Concurrency

`*-concurrency.mjs` scripts (chat, imports, reviews, recurring occurrences, reservations) open separate authenticated and service connections to check locks, cancellation and duplicate claims. They create synthetic users or a disposable schema, remove them by exact ID, and leave a recovery note in ignored `.qa/` files if interrupted.

## Live checks

- `precision.mjs` reads Money and budget pages through PostgREST with amounts beyond JavaScript's safe integer range.
- `summary-live.mjs` (with the app running) checks scheduled summaries end to end: dispatch, deduplication per period, cancellation and disabling.
- Opt-in unit tests compare SQL with application logic, for example `RUN_RESERVATION_DB_TESTS=1 npm test -- lib/finance/reservation-balance.live.test.ts` (PowerShell: `$env:RUN_RESERVATION_DB_TESTS='1'` first).

None of these touch the owner's workspace. Migrations themselves are applied by `npm run setup`.

