1	// Runs this checkout's app for tests on http://localhost:3100, against the moneo-qa backend in
2	// .env.qa (npm run setup -- --qa). Bank access is off and the AI key is a placeholder that every
3	// provider rejects, so nothing costs money; scheduled jobs only see the test backend. It builds into
4	// .next-qa, so it can run beside the owner's app. Playwright starts it on its own.
5	//   npm run qa:server                  (dev server)
6	//   npm run qa:server -- --production  (build, then start)
7	import { execFileSync, spawn } from "node:child_process";
8	import { existsSync, readFileSync } from "node:fs";
9	import { parseEnv } from "node:util";
10	
11	if (!existsSync(".env.qa")) throw new Error("No .env.qa: run `npm run setup -- --qa` first.");
12	const qa = parseEnv(readFileSync(".env.qa", "utf8"));
13	// Next also reads .env; an empty value here keeps every owner setting from leaking in.
14	const names = file => existsSync(file) ? [...readFileSync(file, "utf8").matchAll(/^#?\s*([A-Z][A-Z0-9_]*)=/gm)].map(match => match[1]) : [];
15	const blank = Object.fromEntries([...names(".env.example"), ...names(".env")].map(name => [name, ""]));
16	// The app treats AI as set up, but a real call fails. Specs that call the real model (E2E_REAL_AI=1)
17	// take the key from .env.qa instead.
18	const paid = process.env.E2E_REAL_AI === "1" ? {} : { OPENAI_API_KEY: "sk-qa-placeholder-not-a-real-key", OPENROUTER_API_KEY: "" };
19	const env = {
20	  ...process.env, ...blank, ...qa, ...paid,
21	  ENABLE_BANKING_APP_ID: "", ENABLE_BANKING_PRIVATE_KEY: "",
22	  PORT: "3100", NEXT_PUBLIC_APP_URL: "http://localhost:3100", WORKFLOW_LOCAL_BASE_URL: "http://127.0.0.1:3100", NEXT_DIST_DIR: ".next-qa",
23	};
24	const next = "node_modules/next/dist/bin/next";
25	const production = process.argv.includes("--production");
26	if (production) execFileSync(process.execPath, [next, "build"], { env, stdio: "inherit" });
27	const server = spawn(process.execPath, [next, production ? "start" : "dev", "-H", "127.0.0.1", "-p", "3100"], { env, stdio: "inherit" });
28	for (const signal of ["SIGINT", "SIGTERM"]) process.on(signal, () => server.kill(signal));
29	server.on("exit", code => process.exit(code ?? 0));

